package com.pablo.controlgastos;

import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.Bundle;import android.provider.Settings;import android.widget.*;

public class NotificationSetupActivity extends Activity{
 @Override public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);boolean l=ThemePrefs.isLight(this);int bg=l?Color.rgb(246,248,249):Color.rgb(11,18,24),text=l?Color.rgb(31,38,44):Color.rgb(242,245,247),muted=l?Color.DKGRAY:Color.LTGRAY;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(32,28,32,28);root.setBackgroundColor(bg);TextView t=new TextView(this);t.setText("Activar lectura de notificaciones");t.setTextSize(24);t.setTextColor(text);root.addView(t);TextView info=new TextView(this);info.setText("Si instalaste ControlGastos mediante APK, Android puede bloquear este permiso como configuración restringida.\n\n1. Mantené presionado el icono de ControlGastos y entrá en Información de la aplicación.\n2. Abrí el menú de la pantalla de información y habilitá “Permitir configuraciones restringidas” (el nombre puede variar según el teléfono).\n3. Volvé a ControlGastos.\n4. Entrá en Acceso a notificaciones y activá ControlGastos.\n\nSi el interruptor de notificaciones aparece bloqueado o no te deja activarlo, falta completar el paso 2.");info.setTextSize(16);info.setTextColor(muted);info.setPadding(0,24,0,24);root.addView(info);Button appInfo=new Button(this);appInfo.setText("1 · Abrir información de la app");appInfo.setOnClickListener(v->{Intent i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()));startActivity(i);});root.addView(appInfo);Button notif=new Button(this);notif.setText("2 · Abrir acceso a notificaciones");notif.setOnClickListener(v->{try{startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}});root.addView(notif);setContentView(root);}
}
